import type { BankQuestion } from "@/lib/bank";

/** Algebra, Geometry and Trigonometry (SSC) (Quantitative Aptitude): 155 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "quant-algebra-geometry-1", "question": "If x + 1/x = 3, then x² + 1/x² equals:", "options": ["7", "11", "5", "9"], "answer": 0, "explanation": "Square both sides: x² + 2 + 1/x² = 9, so x² + 1/x² = 7.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "quant-algebra-geometry-2", "question": "The value of sin 30° + cos 60° is:", "options": ["1", "√3", "1/2", "√3/2"], "answer": 0, "explanation": "sin 30° = 1/2 and cos 60° = 1/2, so the sum is 1.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "quant-algebra-geometry-3", "question": "The sum of the interior angles of a hexagon is:", "options": ["720°", "540°", "360°", "900°"], "answer": 0, "explanation": "Sum = (n − 2) × 180° = 4 × 180° = 720°.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "quant-algebra-geometry-4", "question": "If a + b = 5 and ab = 6, then a² + b² equals:", "options": ["11", "25", "19", "13"], "answer": 3, "explanation": "a² + b² = (a + b)² − 2ab = 25 − 12 = 13.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "quant-algebra-geometry-5", "question": "If x + 1/x = 4, then x³ + 1/x³ equals:", "options": ["60", "64", "76", "52"], "answer": 3, "explanation": "x³ + 1/x³ = (x + 1/x)³ − 3(x + 1/x) = 64 − 12 = 52.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-6", "question": "If a + b = 10 and ab = 21, then a³ + b³ equals:", "options": ["1000", "430", "370", "340"], "answer": 2, "explanation": "a³ + b³ = (a + b)³ − 3ab(a + b) = 1000 − 630 = 370.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-7", "question": "The centroid of a triangle divides each median, measured from the vertex, in the ratio:", "options": ["1 : 2", "3 : 1", "1 : 1", "2 : 1"], "answer": 3, "explanation": "The centroid is two-thirds of the way along each median from the vertex, so the ratio from the vertex is 2 : 1.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "quant-algebra-geometry-8", "question": "An arc of a circle subtends 110° at the centre. What angle does it subtend at a point on the remaining part of the circle?", "options": ["70°", "125°", "55°", "110°"], "answer": 2, "explanation": "The angle at the circumference is half the central angle on the same arc: 110°/2 = 55°. 125° would be the angle from a point on the minor arc itself.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "quant-algebra-geometry-9", "question": "The value of tan 45° + sec 60° − cosec 30° is:", "options": ["1", "2", "0", "3"], "answer": 0, "explanation": "tan 45° = 1, sec 60° = 2 and cosec 30° = 2, so the value is 1 + 2 − 2 = 1.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "quant-algebra-geometry-10", "question": "The angle of elevation of the top of a 50 m tall tower from a point on the ground is 30°. How far is the point from the foot of the tower?", "options": ["25√3 m", "100 m", "50/√3 m", "50√3 m"], "answer": 3, "explanation": "tan 30° = 50/d gives d = 50/(1/√3) = 50√3 m (about 86.6 m).", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "quant-algebra-geometry-11", "question": "In triangle ABC, ∠A = 70° and the bisectors of ∠B and ∠C meet at the incentre I. What is ∠BIC?", "options": ["135°", "125°", "110°", "145°"], "answer": 1, "explanation": "∠BIC = 90° + ∠A/2 = 90° + 35° = 125°.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-12", "question": "If 2x + 3y = 12 and xy = 6, then 4x² + 9y² equals:", "options": ["144", "36", "72", "108"], "answer": 2, "explanation": "4x² + 9y² = (2x + 3y)² − 12xy = 144 − 72 = 72.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-13", "question": "If x − 1/x = 3, then x⁴ + 1/x⁴ equals:", "options": ["119", "121", "123", "79"], "answer": 0, "explanation": "x² + 1/x² = 3² + 2 = 11, then x⁴ + 1/x⁴ = 11² − 2 = 119.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-14", "question": "If a + b + c = 9 and ab + bc + ca = 26, then a² + b² + c² equals:", "options": ["29", "107", "55", "26"], "answer": 0, "explanation": "a² + b² + c² = (a + b + c)² − 2(ab + bc + ca) = 81 − 52 = 29.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-15", "question": "If a = 23, b = 24 and c = −47, then a³ + b³ + c³ equals:", "options": ["77,832", "−25,944", "0", "−77,832"], "answer": 3, "explanation": "a + b + c = 0, so a³ + b³ + c³ = 3abc = 3 × 23 × 24 × (−47) = −77,832.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-16", "question": "H is the orthocentre of triangle ABC. If ∠A = 65°, then ∠BHC equals:", "options": ["122.5°", "115°", "130°", "65°"], "answer": 1, "explanation": "For an acute triangle, ∠BHC = 180° − ∠A = 115°. 130° is the circumcentre result (2A) and 122.5° the incentre result (90° + A/2).", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-17", "question": "O is the circumcentre of an acute triangle ABC and ∠OBC = 25°. What is ∠BAC?", "options": ["65°", "50°", "115°", "130°"], "answer": 0, "explanation": "OB = OC, so ∠OCB = 25° and ∠BOC = 130°. The angle at A is half the central angle: 65°.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-18", "question": "PA and PB are tangents from an external point P to a circle with centre O. If ∠APB = 50°, what is ∠OAB?", "options": ["40°", "65°", "50°", "25°"], "answer": 3, "explanation": "∠AOB = 180° − 50° = 130° (OAPB has two right angles). Triangle OAB is isosceles, so ∠OAB = (180° − 130°)/2 = 25°.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-19", "question": "If sin θ + cos θ = √2 cos θ, then cot θ equals:", "options": ["1/√2", "√2 − 1", "√2", "√2 + 1"], "answer": 3, "explanation": "sin θ = (√2 − 1) cos θ, so tan θ = √2 − 1 and cot θ = 1/(√2 − 1) = √2 + 1.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-20", "question": "If sec θ + tan θ = 3, then sec θ equals:", "options": ["5/4", "4/3", "3/5", "5/3"], "answer": 3, "explanation": "Since sec²θ − tan²θ = 1, sec θ − tan θ = 1/3. Adding: 2 sec θ = 10/3, so sec θ = 5/3 (and tan θ = 4/3).", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-21", "question": "From the top of a 60 m tall building, the angles of depression of the top and the foot of a tower are 30° and 60°. What is the height of the tower?", "options": ["40 m", "45 m", "20 m", "30 m"], "answer": 0, "explanation": "Distance = 60/tan 60° = 20√3 m. The drop to the tower’s top = 20√3 × tan 30° = 20 m, so the tower is 60 − 20 = 40 m.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "quant-algebra-geometry-22", "question": "In triangle ABC, DE ∥ BC with D on AB and E on AC, and AD : DB = 2 : 3. What is the ratio of the area of triangle ADE to the area of trapezium DBCE?", "options": ["4 : 9", "4 : 21", "2 : 3", "4 : 25"], "answer": 1, "explanation": "AD : AB = 2 : 5, so the areas of ADE and ABC are 4 : 25 and the trapezium is 25 − 4 = 21 parts: 4 : 21.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-23", "question": "If x = √3 + √2, then x² + 1/x² equals:", "options": ["12", "10", "8", "14"], "answer": 1, "explanation": "1/x = √3 − √2, so x + 1/x = 2√3 and x² + 1/x² = 12 − 2 = 10.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-24", "question": "ABCD is a cyclic quadrilateral with ∠A = (2x + 10)° and ∠C = (3x − 5)°. What is ∠A?", "options": ["80°", "100°", "90°", "70°"], "answer": 0, "explanation": "Opposite angles of a cyclic quadrilateral add up to 180°: 5x + 5 = 180, x = 35, so ∠A = 80° (and ∠C = 100°).", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-25", "question": "If x + 1/x = √5, then x⁵ + 1/x⁵ equals:", "options": ["6√5", "3√5", "4√5", "5√5"], "answer": 3, "explanation": "x² + 1/x² = 3 and x³ + 1/x³ = 5√5 − 3√5 = 2√5. Then x⁵ + 1/x⁵ = (x² + 1/x²)(x³ + 1/x³) − (x + 1/x) = 6√5 − √5 = 5√5.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-26", "question": "If a² + b² + c² − ab − bc − ca = 0 and a + b + c = 12, then a³ + b³ + c³ equals:", "options": ["216", "64", "192", "144"], "answer": 2, "explanation": "The condition equals ½[(a − b)² + (b − c)² + (c − a)²] = 0, so a = b = c = 4 and a³ + b³ + c³ = 3 × 64 = 192.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-27", "question": "If x = 2 + √3, then x⁴ + 1/x⁴ equals:", "options": ["198", "196", "192", "194"], "answer": 3, "explanation": "1/x = 2 − √3, so x + 1/x = 4, x² + 1/x² = 14 and x⁴ + 1/x⁴ = 196 − 2 = 194.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-28", "question": "If a − b = 4 and a³ − b³ = 208, then a² + b² equals:", "options": ["52", "28", "12", "40"], "answer": 3, "explanation": "a³ − b³ = (a − b)³ + 3ab(a − b): 208 = 64 + 12ab, so ab = 12. Then a² + b² = (a − b)² + 2ab = 16 + 24 = 40.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-29", "question": "How many of these statements are correct? I. The incentre always lies inside the triangle. II. The orthocentre of a right-angled triangle is the vertex of the right angle. III. The circumcentre of an obtuse-angled triangle lies inside it. IV. The centroid, circumcentre and orthocentre of a triangle are collinear.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV (the Euler line) are correct. III is wrong: an obtuse triangle’s circumcentre lies outside, beyond the longest side.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-30", "question": "The angle of elevation of the top of a tower from a point A on the ground is 30°. After walking 40 m towards the tower, the angle becomes 60°. What is the height of the tower?", "options": ["20 m", "40 m", "20√3 m", "40√3 m"], "answer": 2, "explanation": "If x is the final distance, h = x√3 and h = (x + 40)/√3, so 3x = x + 40 and x = 20. Then h = 20√3 m ≈ 34.6 m.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "quant-algebra-geometry-31", "question": "If tan θ + cot θ = 2, then tan¹⁰⁰θ + cot¹⁰⁰θ equals:", "options": ["0", "2", "2¹⁰⁰", "1"], "answer": 1, "explanation": "t + 1/t = 2 means (t − 1)² = 0, so tan θ = 1 = cot θ and the sum is 1 + 1 = 2.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-32", "question": "If sin A + sin²A = 1, then cos²A + cos⁴A equals:", "options": ["1/2", "0", "2", "1"], "answer": 3, "explanation": "sin A = 1 − sin²A = cos²A, so cos²A + cos⁴A = sin A + sin²A = 1.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-33", "question": "In triangle ABC, right-angled at B, AB = 6 cm and BC = 8 cm. What is the distance between its centroid and its circumcentre?", "options": ["2 cm", "5 cm", "10/3 cm", "5/3 cm"], "answer": 3, "explanation": "AC = 10 and the circumcentre M is the midpoint of AC, with BM = 5. The centroid lies on BM two-thirds of the way from B, so GM = 5/3 cm.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-34", "question": "Two parallel chords of a circle of radius 10 cm are 16 cm and 12 cm long and lie on opposite sides of the centre. What is the distance between them?", "options": ["10 cm", "12 cm", "2 cm", "14 cm"], "answer": 3, "explanation": "Distances from the centre: √(100 − 64) = 6 and √(100 − 36) = 8. On opposite sides they add: 14 cm (2 cm if on the same side).", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-35", "question": "The minimum value of 9 tan²θ + 4 cot²θ is:", "options": ["6", "36", "13", "12"], "answer": 3, "explanation": "By AM ≥ GM, 9 tan²θ + 4 cot²θ ≥ 2√(9 × 4) = 12, reached when tan²θ = 2/3.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-36", "question": "If x² − 3x + 1 = 0, then x⁶ + 1/x⁶ equals:", "options": ["324", "322", "318", "326"], "answer": 1, "explanation": "Dividing by x: x + 1/x = 3. Then x³ + 1/x³ = 27 − 9 = 18 and x⁶ + 1/x⁶ = 18² − 2 = 322.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-37", "question": "In triangle ABC, the bisector of ∠A meets BC at D. If AB = 12 cm, AC = 8 cm and BC = 15 cm, then BD equals:", "options": ["7.5 cm", "6 cm", "9 cm", "10 cm"], "answer": 2, "explanation": "By the angle-bisector theorem BD : DC = AB : AC = 3 : 2, so BD = 3/5 × 15 = 9 cm.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-38", "question": "The value of sin²1° + sin²2° + sin²3° + … + sin²89° is:", "options": ["89", "44", "44.5", "45"], "answer": 2, "explanation": "Pair sin²k° with sin²(90 − k)° = cos²k°, giving 1 per pair: 44 pairs (1° to 44° with 89° to 46°) plus sin²45° = 1/2, total 44.5.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-39", "question": "If x + 1/x = 1, then x³ + 1/x³ equals:", "options": ["−2", "−1", "0", "2"], "answer": 0, "explanation": "x³ + 1/x³ = 1³ − 3 × 1 = −2. (Indeed x² − x + 1 = 0 gives x³ = −1, so x³ + 1/x³ = −1 − 1 = −2.)", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-40", "question": "A 1.6 m tall observer sees the top of a 21.6 m tall tower at an angle of elevation of 45°. He walks towards the tower until the angle becomes 60°. How far did he walk?", "options": ["20(√3 − 1) m", "20/√3 m", "20(1 − 1/√3) m", "21.6(1 − 1/√3) m"], "answer": 2, "explanation": "Measured from eye level the tower rises 21.6 − 1.6 = 20 m. Distances: 20/tan 45° = 20 and 20/tan 60° = 20/√3, so he walked 20(1 − 1/√3) ≈ 8.45 m. Using 21.6 m forgets the observer’s height.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-41", "question": "What is each interior angle of a regular octagon?", "options": ["45°", "135°", "120°", "140°"], "answer": 1, "explanation": "Sum of interior angles = (8 − 2) × 180° = 1,080°, so each = 1,080/8 = 135°. 45° is the exterior angle.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-algebra-geometry-42", "question": "What is the value of cos²30° + sin²60°?", "options": ["3/4", "3/2", "1", "1/2"], "answer": 1, "explanation": "cos 30° = sin 60° = √3/2, so the sum is 3/4 + 3/4 = 3/2. It is not 1, because the angles are not the same.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-algebra-geometry-43", "question": "(a + b)² − (a − b)² is equal to:", "options": ["2ab", "0", "4ab", "2(a² + b²)"], "answer": 2, "explanation": "(a² + 2ab + b²) − (a² − 2ab + b²) = 4ab. 2(a² + b²) is the sum, not the difference.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-algebra-geometry-44", "question": "What is the slope of the line 3x + 4y = 12?", "options": ["4/3", "−3/4", "3/4", "−4/3"], "answer": 1, "explanation": "y = −(3/4)x + 3, so the slope is −3/4.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-algebra-geometry-45", "question": "One angle of a triangle is 50° and the other two angles are equal. What is each of them?", "options": ["130°", "65°", "75°", "50°"], "answer": 1, "explanation": "The other two share 180° − 50° = 130°, so each is 65°.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-algebra-geometry-46", "question": "If x − 1/x = 4, then x³ − 1/x³ equals:", "options": ["64", "52", "76", "68"], "answer": 2, "explanation": "x³ − 1/x³ = (x − 1/x)³ + 3(x − 1/x) = 64 + 12 = 76. Subtracting 3 × 4 (as for a sum) gives 52.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-47", "question": "If a + b + c = 0 (a, b, c non-zero), then a²/bc + b²/ca + c²/ab equals:", "options": ["abc", "0", "1", "3"], "answer": 3, "explanation": "The expression = (a³ + b³ + c³)/abc, and when a + b + c = 0, a³ + b³ + c³ = 3abc, so it equals 3.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-48", "question": "√(7 + 4√3) is equal to:", "options": ["2 + √3", "4 + √3", "2√3 + 1", "√3 + 1"], "answer": 0, "explanation": "7 + 4√3 = 4 + 3 + 2 × 2 × √3 = (2 + √3)², so the square root is 2 + √3.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-49", "question": "What is the area of the triangle formed by the line 3x + 4y = 12 and the coordinate axes?", "options": ["6 sq units", "12 sq units", "7 sq units", "24 sq units"], "answer": 0, "explanation": "The intercepts are x = 4 and y = 3, so the area = ½ × 4 × 3 = 6 sq units. 12 forgets the ½.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-50", "question": "How many diagonals does a polygon with 12 sides have?", "options": ["54", "60", "66", "48"], "answer": 0, "explanation": "Diagonals = n(n − 3)/2 = 12 × 9/2 = 54. 66 = ¹²C₂ also counts the 12 sides.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-51", "question": "Each exterior angle of a regular polygon is 24°. How many sides does it have?", "options": ["18", "12", "15", "24"], "answer": 2, "explanation": "The exterior angles add up to 360°, so the number of sides = 360/24 = 15.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-52", "question": "What is the value of tan 1° × tan 2° × tan 3° × … × tan 89°?", "options": ["1", "0", "Not defined", "√3"], "answer": 0, "explanation": "Pair tan θ with tan(90° − θ) = cot θ: each pair gives 1, and the middle term tan 45° = 1, so the product is 1.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-53", "question": "A 13 m long ladder rests against a wall and reaches a window 12 m above the ground. How far is the foot of the ladder from the wall?", "options": ["1 m", "6 m", "5 m", "√313 m"], "answer": 2, "explanation": "By Pythagoras, distance = √(13² − 12²) = √25 = 5 m.", "difficulty": "moderate", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-algebra-geometry-54", "question": "What is the distance between the points (3, −4) and (−5, 2)?", "options": ["10 units", "14 units", "8 units", "√68 units"], "answer": 0, "explanation": "Distance = √[(3 + 5)² + (−4 − 2)²] = √(64 + 36) = 10. √68 comes from subtracting −5 and −4 with the wrong signs.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-algebra-geometry-55", "question": "If x² − 5x + 1 = 0, then x³ + 1/x³ equals:", "options": ["140", "125", "115", "110"], "answer": 3, "explanation": "Dividing by x gives x + 1/x = 5, so x³ + 1/x³ = 5³ − 3 × 5 = 125 − 15 = 110.", "difficulty": "hard", "source": "SSC CGL Tier 2 · SSC CHSL"},
  {"id": "quant-algebra-geometry-56", "question": "If α and β are the roots of x² − 7x + 10 = 0, then α² + β² equals:", "options": ["49", "29", "20", "69"], "answer": 1, "explanation": "α + β = 7 and αβ = 10, so α² + β² = 49 − 20 = 29 (the roots are 2 and 5: 4 + 25 = 29).", "difficulty": "hard", "source": "SSC CGL Tier 2 · SSC CHSL"},
  {"id": "quant-algebra-geometry-57", "question": "What is the remainder when x³ − 2x² + 4x − 5 is divided by (x − 2)?", "options": ["11", "3", "−3", "−5"], "answer": 1, "explanation": "By the remainder theorem, put x = 2: 8 − 8 + 8 − 5 = 3.", "difficulty": "hard", "source": "SSC CGL Tier 2 · SSC CHSL"},
  {"id": "quant-algebra-geometry-58", "question": "What is the maximum value of 5 sin θ + 12 cos θ?", "options": ["7", "12", "13", "17"], "answer": 2, "explanation": "The maximum of a sin θ + b cos θ is √(a² + b²) = √(25 + 144) = 13. Adding 5 + 12 = 17 ignores that sin θ and cos θ cannot both be 1.", "difficulty": "hard", "source": "SSC CGL Tier 2 · SSC CHSL"},
  {"id": "quant-algebra-geometry-59", "question": "sin⁶θ + cos⁶θ + 3 sin²θ cos²θ equals:", "options": ["1", "3", "0", "2"], "answer": 0, "explanation": "a³ + b³ = (a + b)³ − 3ab(a + b) with a = sin²θ, b = cos²θ, a + b = 1 gives sin⁶θ + cos⁶θ = 1 − 3 sin²θ cos²θ, so the expression is 1.", "difficulty": "hard", "source": "SSC CGL Tier 2 · SSC CHSL"},
  {"id": "quant-algebra-geometry-60", "question": "Two circles of radii 8 cm and 3 cm have their centres 13 cm apart. What is the length of a direct common tangent?", "options": ["10 cm", "11 cm", "√120 cm", "12 cm"], "answer": 3, "explanation": "Direct common tangent = √[d² − (r₁ − r₂)²] = √(169 − 25) = 12 cm. Using (r₁ + r₂)² gives √48, the transverse tangent.", "difficulty": "hard", "source": "SSC CGL Tier 2 · SSC CHSL"},
  {"id": "quant-algebra-geometry-61", "question": "In a triangle with sides 6 cm, 8 cm and 10 cm, what is the length of the median drawn to the longest side?", "options": ["5 cm", "6 cm", "√73 cm", "4.8 cm"], "answer": 0, "explanation": "By Apollonius, m = ½√(2 × 36 + 2 × 64 − 100) = ½√100 = 5 cm (the median to the hypotenuse equals half of it). 4.8 cm is the altitude.", "difficulty": "hard", "source": "SSC CGL Tier 2 · SSC CHSL"},
  {"id": "quant-algebra-geometry-62", "question": "What are the coordinates of the point that divides the line segment joining (2, 3) and (8, 9) internally in the ratio 1 : 2?", "options": ["(4, 5)", "(6, 7)", "(5, 6)", "(4, 6)"], "answer": 0, "explanation": "Point = ((1 × 8 + 2 × 2)/3, (1 × 9 + 2 × 3)/3) = (12/3, 15/3) = (4, 5). (6, 7) divides it in the ratio 2 : 1.", "difficulty": "hard", "source": "SSC CGL Tier 2 · SSC CHSL"},
  {"id": "quant-algebra-geometry-63", "question": "From an external point P, a tangent PT and a secant PAB are drawn to a circle, with PA = 4 cm and AB = 5 cm. What is PT?", "options": ["9 cm", "√20 cm", "6 cm", "4.5 cm"], "answer": 2, "explanation": "PT² = PA × PB = 4 × (4 + 5) = 36, so PT = 6 cm. Using PA × AB = 20 is the common slip.", "difficulty": "hard", "source": "SSC CGL Tier 2 · SSC CHSL"},
  {"id": "quant-algebra-geometry-64", "question": "The angles of a triangle are in the ratio 2 : 3 : 4. What is the difference between the largest and the smallest angle?", "options": ["80°", "40°", "60°", "20°"], "answer": 1, "explanation": "The angles are 40°, 60° and 80° (180/9 = 20 per part), so the difference is 80° − 40° = 40°.", "difficulty": "hard", "source": "SSC CGL Tier 2 · SSC CHSL"},
  {"id": "quant-algebra-geometry-65", "question": "If 9ˣ = 27ˣ⁻¹, then x equals:", "options": ["2", "3", "1", "−3"], "answer": 1, "explanation": "3²ˣ = 3³⁽ˣ⁻¹⁾, so 2x = 3x − 3 and x = 3.", "difficulty": "hard", "source": "SSC CGL Tier 2 · SSC CHSL"},
  {"id": "quant-algebra-geometry-66", "question": "The shadow of a tower is √3 times its height. What is the angle of elevation of the sun?", "options": ["30°", "60°", "15°", "45°"], "answer": 0, "explanation": "tan θ = height/shadow = 1/√3, so θ = 30°. 60° comes from inverting the ratio.", "difficulty": "hard", "source": "SSC CGL Tier 2 · SSC CHSL"},
  {"id": "quant-algebra-geometry-67", "question": "In triangle ABC, AB = 13 cm, AC = 15 cm and BC = 14 cm. AD is perpendicular to BC. What is AD?", "options": ["12 cm", "11 cm", "14 cm", "13.5 cm"], "answer": 0, "explanation": "By Heron's formula, s = 21 and area = √(21 × 8 × 6 × 7) = 84 cm². AD = 2 × 84/14 = 12 cm.", "difficulty": "hard", "source": "SSC CGL Tier 2 · SSC CHSL"},
  {"id": "quant-algebra-geometry-68", "question": "How many of the following statements are correct?\nI. The angle in a semicircle is a right angle.\nII. The opposite angles of a cyclic quadrilateral are equal.\nIII. The tangent at any point of a circle is perpendicular to the radius through that point.\nIV. Equal chords of a circle subtend equal angles at the centre.", "options": ["All four", "Only two", "Only one", "Only three"], "answer": 3, "explanation": "I, III and IV are true. II is false: the opposite angles of a cyclic quadrilateral are supplementary (they add up to 180°), not equal.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-algebra-geometry-69", "question": "If a + b + c = 6, a² + b² + c² = 14 and a³ + b³ + c³ = 36, then abc equals:", "options": ["12", "6", "11", "4"], "answer": 1, "explanation": "ab + bc + ca = (36 − 14)/2 = 11. a³ + b³ + c³ − 3abc = (a + b + c)(a² + b² + c² − ab − bc − ca) gives 36 − 3abc = 6 × 3 = 18, so abc = 6 (a, b, c = 1, 2, 3). 11 is ab + bc + ca.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-algebra-geometry-70", "question": "If a = 2025, b = 2024 and c = 2023, then a³ + b³ + c³ − 3abc equals:", "options": ["12,144", "18,216", "0", "6,072"], "answer": 1, "explanation": "a³ + b³ + c³ − 3abc = ½(a + b + c)[(a − b)² + (b − c)² + (c − a)²] = ½ × 6,072 × (1 + 1 + 4) = 18,216.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-algebra-geometry-71", "question": "If x = 1/(√2 + 1), then x² + 2x equals:", "options": ["√2", "2", "3 − 2√2", "1"], "answer": 3, "explanation": "Rationalising, x = √2 − 1, so x + 1 = √2 and x² + 2x = (x + 1)² − 1 = 2 − 1 = 1. 3 − 2√2 is x² alone.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-algebra-geometry-72", "question": "What is the value of (√5 + √3)/(√5 − √3) + (√5 − √3)/(√5 + √3)?", "options": ["4", "2√15", "8", "16"], "answer": 2, "explanation": "Over the common denominator 5 − 3 = 2: [(√5 + √3)² + (√5 − √3)²]/2 = [2(5 + 3)]/2 = 8.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-algebra-geometry-73", "question": "If cosec θ − cot θ = 1/2, then cos θ equals:", "options": ["3/4", "4/5", "5/4", "3/5"], "answer": 3, "explanation": "Since cosec²θ − cot²θ = 1, cosec θ + cot θ = 2. Adding and subtracting: cosec θ = 5/4 and cot θ = 3/4, so cos θ = cot θ/cosec θ = 3/5. 4/5 is sin θ.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-algebra-geometry-74", "question": "Two towers of equal height stand 80 m apart. From a point on the ground between them, the angles of elevation of their tops are 60° and 30°. What is the height of each tower?", "options": ["40√3 m", "20 m", "20√3 m", "40 m"], "answer": 2, "explanation": "If the height is h, the distances to the feet are h/√3 and h√3, so h/√3 + h√3 = 4h/√3 = 80 and h = 20√3 m (≈ 34.6 m).", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-algebra-geometry-75", "question": "From the top of a 100 m high cliff, the angles of depression of two boats on the same side, in line with the foot of the cliff, are 60° and 45°. What is the distance between the boats?", "options": ["50(3 − √3) m", "100√3 m", "100(√3 − 1) m", "100(3 − √3)/3 m"], "answer": 3, "explanation": "The boats are 100/tan 45° = 100 m and 100/tan 60° = 100/√3 m from the foot. Distance = 100 − 100/√3 = 100(3 − √3)/3 m ≈ 42.3 m.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-algebra-geometry-76", "question": "For how many real values of k is the area of the triangle with vertices (0, 0), (4, 0) and (k, 6) equal to 12 square units?", "options": ["Only k = 2", "No value of k", "Only k = 0", "Every real value of k"], "answer": 3, "explanation": "The base on the x-axis is 4 and the height is always 6 (the y-coordinate of the third vertex), so the area is ½ × 4 × 6 = 12 whatever k is.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-algebra-geometry-77", "question": "For a triangle with sides 7 cm, 24 cm and 25 cm, what is the sum of its circumradius and its inradius?", "options": ["16 cm", "15 cm", "15.5 cm", "12.5 cm"], "answer": 2, "explanation": "It is right-angled (49 + 576 = 625), so R = 25/2 = 12.5 cm and r = (7 + 24 − 25)/2 = 3 cm. Sum = 15.5 cm.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-algebra-geometry-78", "question": "The three medians of a triangle are 9 cm, 12 cm and 15 cm long. What is the area of the triangle?", "options": ["36 cm²", "54 cm²", "72 cm²", "108 cm²"], "answer": 2, "explanation": "Area of a triangle = 4/3 × area of the triangle formed by its medians. The medians 9, 12, 15 form a right triangle of area 54, so the area = 4/3 × 54 = 72 cm².", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-algebra-geometry-79", "question": "How many triangles with integer sides have a perimeter of 12 units?", "options": ["4", "2", "5", "3"], "answer": 3, "explanation": "Each side must be less than half the perimeter (< 6): (2, 5, 5), (3, 4, 5) and (4, 4, 4). So 3 triangles.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-algebra-geometry-80", "question": "A chord of a circle of radius 6 cm subtends an angle of 120° at the centre. What is the area of the minor segment it cuts off?", "options": ["(12π − 9√3) cm²", "12π cm²", "(6π − 9√3) cm²", "(12π − 18√3) cm²"], "answer": 0, "explanation": "Sector = 120/360 × π × 36 = 12π. Triangle = ½ × 6 × 6 × sin 120° = 9√3. Segment = 12π − 9√3 cm² (≈ 22.1 cm²).", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-algebra-geometry-81", "question": "TA is a tangent to a circle at A, and AB is a chord with ∠TAB = 65°. D is a point on the minor arc AB (the arc on the same side as T). What is ∠ADB?", "options": ["25°", "115°", "130°", "65°"], "answer": 1, "explanation": "By the alternate segment theorem, the angle in the major segment is 65°. ADB lies in the minor segment, and the angles in the two segments are supplementary: ∠ADB = 180° − 65° = 115°.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-algebra-geometry-82", "question": "Assertion (A): The maximum value of sin θ cos θ is 1/2.\nReason (R): sin θ cos θ = ½ sin 2θ, and the maximum value of sin 2θ is 1.", "options": ["Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "Both A and R are true, and R is the correct explanation of A", "A is false but R is true"], "answer": 2, "explanation": "½ sin 2θ is largest when sin 2θ = 1 (θ = 45°), giving 1/2. A follows from R.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-algebra-geometry-83", "question": "How many integers x satisfy 2x − 5 < 3x + 1 < 2x + 4?", "options": ["7", "9", "6", "8"], "answer": 3, "explanation": "2x − 5 < 3x + 1 gives x > −6; 3x + 1 < 2x + 4 gives x < 3. The integers −5, −4, …, 2 number 8.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-algebra-geometry-84", "question": "For what value of k do the equations kx + 3y = 5 and 4x + 6y = 7 have no solution?", "options": ["4", "3/2", "−2", "2"], "answer": 3, "explanation": "No solution needs parallel lines: k/4 = 3/6 ≠ 5/7, so k = 2. (5/7 ≠ 1/2, so the lines are distinct.)", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-algebra-geometry-85", "question": "(sin θ + cosec θ)² + (cos θ + sec θ)² − (tan²θ + cot²θ) equals:", "options": ["7", "9", "1", "5"], "answer": 0, "explanation": "Expanding: sin²θ + cos²θ + 4 + cosec²θ + sec²θ = 1 + 4 + (1 + cot²θ) + (1 + tan²θ) = 7 + tan²θ + cot²θ. Subtracting tan²θ + cot²θ leaves 7.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-algebra-geometry-86", "question": "What is the value of sin²45° + tan²60° − cos 0°?", "options": ["3/2", "7/2", "5/2", "2"], "answer": 2, "explanation": "sin²45° = 1/2, tan²60° = 3 and cos 0° = 1, so the value is 1/2 + 3 − 1 = 5/2.", "difficulty": "easy", "source": "SSC CHSL · IBPS Clerk"},
  {"id": "quant-algebra-geometry-87", "question": "Each interior angle of a regular polygon is 150°. How many sides does it have?", "options": ["10", "15", "8", "12"], "answer": 3, "explanation": "Exterior angle = 180° − 150° = 30°, and the exterior angles add up to 360°, so n = 360/30 = 12.", "difficulty": "easy", "source": "SSC CHSL · IBPS Clerk"},
  {"id": "quant-algebra-geometry-88", "question": "What is the midpoint of the line segment joining (−2, 7) and (6, −1)?", "options": ["(2, 3)", "(4, 4)", "(2, 4)", "(−4, 4)"], "answer": 0, "explanation": "Midpoint = ((−2 + 6)/2, (7 + (−1))/2) = (2, 3). (4, 4) halves the differences instead of the sums.", "difficulty": "easy", "source": "SSC CHSL · IBPS Clerk"},
  {"id": "quant-algebra-geometry-89", "question": "If x + y = 7 and x − y = 3, what is the value of x² − y² + 2xy?", "options": ["21", "41", "49", "45"], "answer": 1, "explanation": "x² − y² = (x + y)(x − y) = 21, and x = 5, y = 2 give 2xy = 20. Total = 41. 49 is (x + y)², a different expression.", "difficulty": "moderate", "source": "SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id": "quant-algebra-geometry-90", "question": "If a + 1/a = 6 and a > 1, what is the value of a² − 1/a²?", "options": ["32", "34", "24√2", "12√2"], "answer": 2, "explanation": "(a − 1/a)² = (a + 1/a)² − 4 = 32, so a − 1/a = 4√2 (positive as a > 1). a² − 1/a² = (a + 1/a)(a − 1/a) = 6 × 4√2 = 24√2.", "difficulty": "moderate", "source": "SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id": "quant-algebra-geometry-91", "question": "In triangle ABC, ∠B = 90°, AB = 9 cm and AC = 15 cm. What is the value of tan C + sec A?", "options": ["31/12", "7/4", "17/12", "29/12"], "answer": 3, "explanation": "BC = √(225 − 81) = 12. tan C = AB/BC = 3/4 and sec A = AC/AB = 5/3, so the sum is 9/12 + 20/12 = 29/12.", "difficulty": "moderate", "source": "SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id": "quant-algebra-geometry-92", "question": "Two supplementary angles differ by 36°. What is the larger angle?", "options": ["108°", "72°", "126°", "96°"], "answer": 0, "explanation": "Larger = (sum + difference)/2 = (180 + 36)/2 = 108°. 72° is the smaller angle.", "difficulty": "moderate", "source": "SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id": "quant-algebra-geometry-93", "question": "An exterior angle of a triangle is 120°, and its two interior opposite angles are in the ratio 3 : 5. What is the smallest angle of the triangle?", "options": ["60°", "45°", "75°", "40°"], "answer": 1, "explanation": "The interior opposite angles add up to the exterior angle: 3k + 5k = 120°, so they are 45° and 75°. The third angle is 180° − 120° = 60°, so the smallest is 45°.", "difficulty": "moderate", "source": "SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id": "quant-algebra-geometry-94", "question": "A line passes through (2, 3) and is parallel to 2x − 5y + 7 = 0. What is its y-intercept?", "options": ["−11/5", "3/5", "11/5", "11/2"], "answer": 2, "explanation": "A parallel line has slope 2/5: y − 3 = (2/5)(x − 2). At x = 0, y = 3 − 4/5 = 11/5. 11/2 is the size of the x-intercept, not the y-intercept.", "difficulty": "moderate", "source": "SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id": "quant-algebra-geometry-95", "question": "If x = 3 + 2√2, what is the value of x³ + 1/x³?", "options": ["216", "204", "194", "198"], "answer": 3, "explanation": "1/x = 3 − 2√2 (rationalise), so x + 1/x = 6. Then x³ + 1/x³ = 6³ − 3 × 6 = 216 − 18 = 198.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-96", "question": "If a + b + c = 15 and a² + b² + c² = 83, what is the value of a³ + b³ + c³ − 3abc?", "options": ["180", "225", "1245", "150"], "answer": 0, "explanation": "ab + bc + ca = (15² − 83)/2 = 71. a³ + b³ + c³ − 3abc = (a + b + c)(a² + b² + c² − ab − bc − ca) = 15 × (83 − 71) = 180.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-97", "question": "If x, y and z are real numbers such that x² + y² + z² = 2(x − 2y + 3z) − 14, what is the value of x + y + z?", "options": ["6", "2", "0", "4"], "answer": 1, "explanation": "Rearranging: (x − 1)² + (y + 2)² + (z − 3)² = 1 + 4 + 9 − 14 = 0. A sum of squares is zero only if each is zero, so x = 1, y = −2, z = 3 and x + y + z = 2.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-98", "question": "If 3x + 1/(2x) = 5, what is the value of 4x² + 1/(9x²)?", "options": ["25", "76/9", "88/9", "100/9"], "answer": 2, "explanation": "Multiply by 2/3: 2x + 1/(3x) = 10/3. Squaring, 4x² + 1/(9x²) + 2 × 2x × 1/(3x) = 100/9, so 4x² + 1/(9x²) = 100/9 − 4/3 = 88/9.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-99", "question": "If tan θ = 8/15, what is the value of (2 sin θ − cos θ)/(sin θ + 2 cos θ)?", "options": ["1/19", "31/38", "8/19", "1/38"], "answer": 3, "explanation": "Divide top and bottom by cos θ: (2 tan θ − 1)/(tan θ + 2) = (16/15 − 1)/(8/15 + 2) = (1/15)/(38/15) = 1/38.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-100", "question": "In triangle ABC, AB = 10 cm, AC = 14 cm and BC = 16 cm. What is the length of the median AD?", "options": ["2√21 cm", "4√6 cm", "2√37 cm", "12 cm"], "answer": 0, "explanation": "Apollonius: AB² + AC² = 2(AD² + BD²), so 296 = 2(AD² + 64) and AD² = 84. AD = √84 = 2√21 cm.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-101", "question": "Chords AB and CD of a circle intersect at a point P inside it. If AP = 6 cm, PB = 4 cm and CP = 3 cm, what is the length of CD?", "options": ["8 cm", "11 cm", "13 cm", "10 cm"], "answer": 1, "explanation": "Intersecting chords: AP × PB = CP × PD, so PD = 24/3 = 8 cm and CD = 3 + 8 = 11 cm. 8 cm is only PD.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-102", "question": "The incircle of triangle ABC, with AB = 13 cm, BC = 14 cm and CA = 15 cm, touches BC at D. What is BD?", "options": ["7 cm", "8 cm", "6 cm", "5 cm"], "answer": 2, "explanation": "With s = 21, the tangent length from B is BD = s − CA = 21 − 15 = 6 cm (and CD = s − AB = 8 cm). 7 cm assumes D is the midpoint.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-103", "question": "Two points P and Q lie on opposite sides of a tower, in line with its foot, and are 40(3 + √3) m apart. The angles of elevation of the top of the tower from P and Q are 45° and 60°. What is the height of the tower?", "options": ["40√3 m", "60(√3 + 1) m", "80 m", "120 m"], "answer": 3, "explanation": "h + h/√3 = 40(3 + √3). Since 3 + √3 = √3(√3 + 1), h(√3 + 1)/√3 = 40√3(√3 + 1), giving h = 40 × 3 = 120 m.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-104", "question": "If cos θ/(1 − sin θ) + cos θ/(1 + sin θ) = 4 and θ is acute, what is θ?", "options": ["60°", "30°", "45°", "75°"], "answer": 0, "explanation": "The left side = cos θ × 2/(1 − sin²θ) = 2/cos θ = 2 sec θ. So sec θ = 2 and θ = 60°.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-105", "question": "The roots of x² − 9x + k = 0 differ by 3. What is the value of k?", "options": ["20", "18", "14", "27"], "answer": 1, "explanation": "(α − β)² = (α + β)² − 4αβ, so 9 = 81 − 4k and k = 18 (roots 6 and 3). 27 wrongly takes 3 × 9.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-106", "question": "AB is a diameter of a circle and C is a point on the circle with ∠CAB = 28°. The tangent at C meets AB produced beyond B at T. What is ∠CTA?", "options": ["28°", "62°", "34°", "56°"], "answer": 2, "explanation": "∠ACB = 90°, so ∠ABC = 62° and ∠CBT = 118°. By the alternate segment theorem ∠TCB = ∠CAB = 28°. In triangle CBT, ∠CTB = 180° − 118° − 28° = 34°.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-107", "question": "If sec²θ + tan²θ = 7/3, what is the value of sec⁴θ − tan⁴θ?", "options": ["1", "49/9", "4/3", "7/3"], "answer": 3, "explanation": "sec⁴θ − tan⁴θ = (sec²θ − tan²θ)(sec²θ + tan²θ) = 1 × 7/3 = 7/3. No need to find θ.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-108", "question": "For what value of k are the lines 3x + 2ky − 2 = 0 and 2x + 5y + 1 = 0 parallel?", "options": ["15/4", "4/15", "5/3", "−15/4"], "answer": 0, "explanation": "Parallel lines need a₁/a₂ = b₁/b₂: 3/2 = 2k/5, so k = 15/4.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-109", "question": "If x = ∛(2 + √3) + ∛(2 − √3), what is the value of x³ − 3x?", "options": ["2", "4", "1", "3√3"], "answer": 1, "explanation": "Let p and q be the two cube roots, so pq = ∛(4 − 3) = 1. Then x³ = p³ + q³ + 3pq(p + q) = 4 + 3x, so x³ − 3x = 4.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-110", "question": "If a + b + c = 0, what is the value of (a + b)(b + c)(c + a) + abc?", "options": ["abc", "2abc", "0", "−2abc"], "answer": 2, "explanation": "a + b = −c, b + c = −a and c + a = −b, so the product is (−c)(−a)(−b) = −abc. Adding abc gives 0. 2abc forgets the sign.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-111", "question": "If x = 99, what is the value of x(x² + 3x + 3)?", "options": ["10,00,000", "9,99,997", "9,70,299", "9,99,999"], "answer": 3, "explanation": "x³ + 3x² + 3x = (x + 1)³ − 1 = 100³ − 1 = 9,99,999. Spotting the incomplete cube avoids the long multiplication.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-112", "question": "If x⁴ + 1/x⁴ = 322 and x > 1, what is the value of x³ − 1/x³?", "options": ["76", "64", "52", "80"], "answer": 0, "explanation": "x² + 1/x² = √(322 + 2) = 18, so (x − 1/x)² = 16 and x − 1/x = 4. Then x³ − 1/x³ = 4³ + 3 × 4 = 76. 52 subtracts 3 × 4 instead of adding.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-113", "question": "What is the minimum value of 4 sec²θ + 9 cos²θ?", "options": ["13", "12", "6", "36"], "answer": 1, "explanation": "With c = cos²θ, AM ≥ GM gives 4/c + 9c ≥ 2√36 = 12, with equality at c = 2/3, which is allowed. 13 is the trap of putting θ = 0°.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-114", "question": "If sin(A + B) = 1 and cos(A − B) = √3/2, where 0° < B < A < 90°, what is the value of cos(2A + B)?", "options": ["√3/2", "−1/2", "−√3/2", "0"], "answer": 2, "explanation": "A + B = 90° and A − B = 30° give A = 60°, B = 30°. cos(150°) = −cos 30° = −√3/2. The sign trap gives √3/2.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-115", "question": "In triangle ABC, AB = AC and ∠BAC = 40°. D is a point on AC such that BD = BC. What is ∠ABD?", "options": ["40°", "20°", "35°", "30°"], "answer": 3, "explanation": "Base angles are 70° each. In isosceles triangle BDC, ∠BDC = ∠BCD = 70°, so ∠DBC = 40°. ∠ABD = 70° − 40° = 30°.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-116", "question": "Two circles of radii 10 cm and 17 cm intersect, and their common chord is 16 cm long. What is the distance between their centres?", "options": ["21 cm", "9 cm", "27 cm", "24 cm"], "answer": 0, "explanation": "The line of centres bisects the common chord at right angles: distances from the centres are √(100 − 64) = 6 and √(289 − 64) = 15. The centres lie on opposite sides of the chord, so the distance is 21 cm; 9 cm wrongly puts them on the same side.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-117", "question": "In triangle ABC, ∠A = 90° and AD is perpendicular to BC. If BD = 9 cm and DC = 16 cm, what is the area of triangle ABD?", "options": ["150 cm²", "54 cm²", "96 cm²", "108 cm²"], "answer": 1, "explanation": "AD² = BD × DC = 144, so AD = 12 cm. Area of ABD = ½ × 9 × 12 = 54 cm². 150 cm² is the whole triangle and 96 cm² is ADC.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-118", "question": "For how many values of k does x² − (k + 3)x + 4k = 0 have equal roots, and what is the sum of those values?", "options": ["1 value, sum 9", "2 values, sum 9", "2 values, sum 10", "2 values, sum −10"], "answer": 2, "explanation": "Equal roots need (k + 3)² = 16k, i.e. k² − 10k + 9 = 0, so k = 1 or 9: two values with sum 10 (the sum of roots of the quadratic in k).", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-119", "question": "The triangle with vertices (1, 2), (5, 6) and (k, −2) has an area of 12 square units. What is the sum of all possible values of k?", "options": ["3", "−9", "6", "−6"], "answer": 3, "explanation": "Area = ½|1(6 + 2) + 5(−2 − 2) + k(2 − 6)| = ½|−12 − 4k| = 12, so |12 + 4k| = 24, giving k = 3 or −9. Sum = −6.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-120", "question": "If sin⁴θ − cos⁴θ = 1/3, what is the value of tan²θ?", "options": ["2", "1/2", "3", "4/3"], "answer": 0, "explanation": "sin⁴θ − cos⁴θ = (sin²θ − cos²θ)(sin²θ + cos²θ) = sin²θ − cos²θ = 1/3. With sin²θ + cos²θ = 1, sin²θ = 2/3 and cos²θ = 1/3, so tan²θ = 2.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-121", "question": "What is the value of cos 60° × sec 60° + tan 45°?", "options": ["1", "2", "3", "0"], "answer": 1, "explanation": "cos 60° × sec 60° = 1 (reciprocals), and tan 45° = 1, so the value is 2.", "difficulty": "easy", "source": "SSC CHSL · IBPS Clerk"},
  {"id": "quant-algebra-geometry-122", "question": "What is the sum of the exterior angles of a regular decagon?", "options": ["1,440°", "144°", "360°", "180°"], "answer": 2, "explanation": "The exterior angles of any convex polygon add up to 360°. 1,440° is the sum of the interior angles and 144° is one interior angle.", "difficulty": "easy", "source": "SSC CHSL · IBPS Clerk"},
  {"id": "quant-algebra-geometry-123", "question": "What is the slope of the line passing through (1, 2) and (4, 11)?", "options": ["1/3", "−3", "9", "3"], "answer": 3, "explanation": "Slope = (y₂ − y₁)/(x₂ − x₁) = 9/3 = 3. 1/3 inverts the formula.", "difficulty": "easy", "source": "SSC CHSL · IBPS Clerk"},
  {"id": "quant-algebra-geometry-124", "question": "If 5x − 3 = 2x + 9, what is the value of x² − 1?", "options": ["15", "16", "8", "24"], "answer": 0, "explanation": "3x = 12, so x = 4 and x² − 1 = 15. 16 forgets to subtract 1.", "difficulty": "easy", "source": "SSC CHSL · IBPS Clerk"},
  {"id": "quant-algebra-geometry-125", "question": "If x + y = 12 and xy = 32, what is the value of x² + y²?", "options": ["112", "80", "144", "64"], "answer": 1, "explanation": "x² + y² = (x + y)² − 2xy = 144 − 64 = 80. 112 adds 2xy instead of subtracting.", "difficulty": "moderate", "source": "SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id": "quant-algebra-geometry-126", "question": "If a − b = 2 and b − c = 3, what is the value of (a − b)³ + (b − c)³ + (c − a)³?", "options": ["90", "160", "−90", "−160"], "answer": 2, "explanation": "The three brackets add up to 0, so the sum of cubes = 3(a − b)(b − c)(c − a) = 3 × 2 × 3 × (−5) = −90.", "difficulty": "moderate", "source": "SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id": "quant-algebra-geometry-127", "question": "The angles A, B and C of a triangle are in the ratio 1 : 2 : 3. What is the ratio of the sides opposite them?", "options": ["1 : 2 : 3", "1 : √2 : √3", "√3 : 1 : 2", "1 : √3 : 2"], "answer": 3, "explanation": "The angles are 30°, 60° and 90°, and sides are proportional to the sines: 1/2 : √3/2 : 1 = 1 : √3 : 2. Sides are not in the ratio of the angles.", "difficulty": "moderate", "source": "SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id": "quant-algebra-geometry-128", "question": "What is the distance between the parallel lines 3x + 4y = 7 and 3x + 4y = 22?", "options": ["3", "15", "5", "29/5"], "answer": 0, "explanation": "Distance = |c₁ − c₂|/√(a² + b²) = 15/5 = 3 units.", "difficulty": "moderate", "source": "SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id": "quant-algebra-geometry-129", "question": "If sin θ = 3/5 and θ is acute, what is the value of tan θ + sec θ?", "options": ["7/4", "2", "8/5", "3/2"], "answer": 1, "explanation": "cos θ = 4/5, so tan θ = 3/4 and sec θ = 5/4. Their sum is 8/4 = 2.", "difficulty": "moderate", "source": "SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id": "quant-algebra-geometry-130", "question": "If 2ˣ⁺³ = 32ˣ⁻¹, what is the value of x?", "options": ["1", "3", "2", "4"], "answer": 2, "explanation": "32 = 2⁵, so x + 3 = 5(x − 1) = 5x − 5, giving 4x = 8 and x = 2.", "difficulty": "moderate", "source": "SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id": "quant-algebra-geometry-131", "question": "What is the area of the triangle with vertices (0, 0), (6, 0) and (3, 4)?", "options": ["24 sq units", "10 sq units", "15 sq units", "12 sq units"], "answer": 3, "explanation": "The base on the x-axis is 6 and the height is the y-coordinate 4, so area = ½ × 6 × 4 = 12. 24 forgets the ½.", "difficulty": "moderate", "source": "SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id": "quant-algebra-geometry-132", "question": "A chord of length 24 cm is drawn in a circle of radius 13 cm. How far is the chord from the centre?", "options": ["5 cm", "12 cm", "7 cm", "11 cm"], "answer": 0, "explanation": "The perpendicular from the centre bisects the chord: d = √(13² − 12²) = 5 cm. Using the full chord length 24 is the usual slip.", "difficulty": "moderate", "source": "SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id": "quant-algebra-geometry-133", "question": "If x = 1/(3 − 2√2) and y = 1/(3 + 2√2), what is the value of x² + y² − xy?", "options": ["34", "33", "35", "36"], "answer": 1, "explanation": "x = 3 + 2√2 and y = 3 − 2√2, so x + y = 6 and xy = 1. x² + y² − xy = (x + y)² − 3xy = 36 − 3 = 33.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-134", "question": "If a + b = 1 and a³ + b³ = 19, what is the value of ab?", "options": ["6", "−18", "−6", "18"], "answer": 2, "explanation": "a³ + b³ = (a + b)³ − 3ab(a + b) = 1 − 3ab = 19, so ab = −6. (a and b are 3 and −2.)", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-135", "question": "What is the value of √(12 + √(12 + √(12 + …))) continued forever?", "options": ["3", "2√3", "6", "4"], "answer": 3, "explanation": "Let x be the value: x = √(12 + x), so x² − x − 12 = 0 and x = 4 (the root −3 is rejected). Trick: the answer is n + 1 when 12 = n(n + 1).", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-136", "question": "What is the value of tan 15° + cot 15°?", "options": ["4", "2√3", "2", "√3 + 1"], "answer": 0, "explanation": "tan 15° = 2 − √3 and cot 15° = 2 + √3, so the sum is 4. Alternatively tan θ + cot θ = 2/sin 2θ = 2/sin 30° = 4.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-137", "question": "What is the value of sin 75°?", "options": ["(√6 − √2)/4", "(√6 + √2)/4", "(√3 + 1)/2", "√3/2"], "answer": 1, "explanation": "sin(45° + 30°) = sin 45° cos 30° + cos 45° sin 30° = (√3 + 1)/(2√2) = (√6 + √2)/4. The minus version is sin 15°.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-138", "question": "Two circles of radii 9 cm and 4 cm touch each other externally. What is the length of their direct common tangent?", "options": ["13 cm", "5 cm", "12 cm", "6 cm"], "answer": 2, "explanation": "The centres are 9 + 4 = 13 cm apart, so the tangent = √(13² − (9 − 4)²) = 12 cm. Shortcut for touching circles: 2√(r₁r₂) = 2√36 = 12.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-139", "question": "The interior and exterior angles of a regular polygon are in the ratio 7 : 2. How many sides does the polygon have?", "options": ["7", "10", "12", "9"], "answer": 3, "explanation": "Exterior = 180° × 2/9 = 40°, so n = 360/40 = 9. Quick rule: interior/exterior = (n − 2)/2 = 7/2 gives n = 9.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-140", "question": "D and E are the midpoints of sides AB and AC of triangle ABC. What is the ratio of the area of triangle ADE to the area of the quadrilateral DBCE?", "options": ["1 : 3", "1 : 4", "1 : 2", "1 : 1"], "answer": 0, "explanation": "Triangle ADE is similar to ABC with ratio 1/2, so its area is 1/4 of ABC. The trapezium is the remaining 3/4, giving 1 : 3. 1 : 4 compares ADE with the whole triangle.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-141", "question": "If cot θ = 7/8, what is the value of (1 + sin θ)(1 − sin θ)/[(1 + cos θ)(1 − cos θ)]?", "options": ["64/49", "49/64", "7/8", "15/64"], "answer": 1, "explanation": "The expression is (1 − sin²θ)/(1 − cos²θ) = cos²θ/sin²θ = cot²θ = 49/64.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-142", "question": "The line 2x + 3y = 12 meets the x-axis at A and the y-axis at B. What is the length of AB?", "options": ["√13", "10", "2√13", "13"], "answer": 2, "explanation": "A = (6, 0) and B = (0, 4). AB = √(36 + 16) = √52 = 2√13 units.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-143", "question": "If x² − 4x + 1 = 0, what is the value of x⁴ + 1/x⁴?", "options": ["196", "192", "14", "194"], "answer": 3, "explanation": "Dividing by x: x + 1/x = 4. Then x² + 1/x² = 16 − 2 = 14 and x⁴ + 1/x⁴ = 196 − 2 = 194.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "quant-algebra-geometry-144", "question": "If 1/a + 1/b + 1/c = 0 and a + b + c = 9, what is the value of a² + b² + c²?", "options": ["81", "9", "27", "0"], "answer": 0, "explanation": "1/a + 1/b + 1/c = (ab + bc + ca)/abc = 0, so ab + bc + ca = 0. Then a² + b² + c² = (a + b + c)² − 2(ab + bc + ca) = 81.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-145", "question": "If x = 2 − ∛2 + ∛4, what is the value of x³ − 6x² + 18x?", "options": ["18", "22", "24", "40"], "answer": 1, "explanation": "With t = ∛2, (x − 2) = t² − t, and cubing gives (x − 2)³ = t⁶ − 3t⁵ + 3t⁴ − t³ = 4 − 6t² + 6t − 2 = 2 − 6(t² − t) = 2 − 6(x − 2). Expanding: x³ − 6x² + 12x − 8 = 14 − 6x, so x³ − 6x² + 18x = 22.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-146", "question": "What is the minimum value of sin²θ + cos⁴θ?", "options": ["1/2", "1", "3/4", "0"], "answer": 2, "explanation": "With s = sin²θ, the expression is s + (1 − s)² = s² − s + 1 = (s − 1/2)² + 3/4, least at s = 1/2. Minimum = 3/4.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-147", "question": "In triangle ABC, ∠A = 90°, AB = 8 cm and AC = 6 cm. The bisector of ∠A meets BC at D. What is BD?", "options": ["30/7 cm", "5 cm", "32/7 cm", "40/7 cm"], "answer": 3, "explanation": "BC = 10 cm, and the bisector divides it in the ratio AB : AC = 4 : 3. BD = 10 × 4/7 = 40/7 cm; 30/7 cm is DC.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-148", "question": "P is a point inside an equilateral triangle of side 12 cm. What is the sum of the perpendicular distances from P to the three sides?", "options": ["6√3 cm", "12 cm", "4√3 cm", "18 cm"], "answer": 0, "explanation": "Splitting the triangle at P: ½ × 12 × (p + q + r) = (√3/4) × 144, so p + q + r = 6√3 cm, the altitude, wherever P is (Viviani's theorem).", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-149", "question": "The vertices of a triangle are (2, 3), (−4, 7) and (8, −4). How far is its centroid from the origin?", "options": ["2 units", "2√2 units", "4 units", "√5 units"], "answer": 1, "explanation": "Centroid = ((2 − 4 + 8)/3, (3 + 7 − 4)/3) = (2, 2). Distance from the origin = √8 = 2√2 units.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-150", "question": "If α and β are the roots of x² − 5x + 3 = 0, what is the value of α/β + β/α?", "options": ["25/3", "31/3", "19/3", "5/3"], "answer": 2, "explanation": "α/β + β/α = (α² + β²)/αβ = ((α + β)² − 2αβ)/αβ = (25 − 6)/3 = 19/3. 25/3 forgets the −2αβ.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-151", "question": "If 3ˣ = 5ʸ = 75ᶻ, which of the following is true?", "options": ["z = xy/(x + 2y)", "z = 2xy/(x + y)", "z = (x + 2y)/xy", "z = xy/(2x + y)"], "answer": 3, "explanation": "Let each equal k: 3 = k^(1/x), 5 = k^(1/y), 75 = k^(1/z). Since 75 = 3 × 5², 1/z = 1/x + 2/y = (y + 2x)/xy, so z = xy/(2x + y).", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-152", "question": "What is the value of sin²5° + sin²10° + sin²15° + … + sin²90°?", "options": ["19/2", "9", "10", "17/2"], "answer": 0, "explanation": "Pair sin²θ with sin²(90° − θ) = cos²θ: (5°, 85°) … (40°, 50°) give 8 pairs of 1. Add sin²45° = 1/2 and sin²90° = 1: total 9.5 = 19/2.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-153", "question": "In triangle ABC, AB = AC = 10 cm and BC = 12 cm. What is the radius of its circumcircle?", "options": ["6 cm", "6.25 cm", "8 cm", "5 cm"], "answer": 1, "explanation": "The altitude to BC is √(100 − 36) = 8, so the area is 48 cm². R = abc/(4 × area) = 1,200/192 = 6.25 cm.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-154", "question": "If (x + 1/x)² = 3, what is the value of x²⁰⁶ + x²⁰⁰ + x⁹⁰ + x⁸⁴ + x¹⁸ + x¹² + x⁶ + 1?", "options": ["1", "2", "0", "8"], "answer": 2, "explanation": "x + 1/x = √3, so x³ + 1/x³ = (√3)³ − 3√3 = 0, i.e. x⁶ = −1. Then x²⁰⁶ = x², x²⁰⁰ = −x², x⁹⁰ = −1, x⁸⁴ = 1, x¹⁸ = −1, x¹² = 1, x⁶ = −1, and everything cancels to 0.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
  {"id": "quant-algebra-geometry-155", "question": "What is the value of (cos 9° + sin 9°)/(cos 9° − sin 9°)?", "options": ["tan 36°", "tan 9°", "1", "cot 36°"], "answer": 3, "explanation": "Divide by cos 9°: (1 + tan 9°)/(1 − tan 9°) = tan(45° + 9°) = tan 54° = cot 36°.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · IBPS PO Mains"},
];

export default questions;
